def bag_coverage(snapshot, options):
    groups = {r['group_id'] for r in snapshot['accounts']}
    sessions = snapshot['sessions']
    return {'groups': len(groups), 'accounts': len(snapshot['accounts']),
            'sessions': len(sessions), 'employees': len({r['employee_hash'] for r in sessions}),
            'known_outcomes': sum(row.get('signed_at') is not None for row in snapshot['outcomes']),
            'withdrawals': len(snapshot['withdrawals'])}

